begin isolation level repeatable read read only; set local statement_timeout='30s'; set local lock_timeout='3s'; select jsonb_build_object('read_only',current_setting('transaction_read_only'),'recorded_at',now(),'sanity',jsonb_build_object('cards',(select count(*) from public.card_prints),'sets',(select count(*) from public.sets),'traits',(select count(*) from public.card_print_traits)),'migrations',(select jsonb_agg(version order by version) from supabase_migrations.schema_migrations),'vendor_tables',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity) order by c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'vendor_%'),'vendor_functions',(select coalesce(jsonb_agg(p.proname order by p.proname),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'vendor_%'),'feature_buckets',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'public',public)),'[]'::jsonb) from storage.buckets where id like 'vendor-%'),'active_store_grants',(select count(*) from public.user_entitlements where is_active and (features->>'store_app'='true' or features->>'store_web'='true'))) as result; rollback;